def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges."""
    result = []
    for start, end in sorted(ranges):
        if start > end:
            raise ValueError("range start exceeds end")
        if result and start <= result[-1][1] + 1:
            previous_start, previous_end = result[-1]
            result[-1] = (previous_start, max(previous_end, end))
        else:
            result.append((start, end))
    return result


def subtract(ranges, holes):
    """Return the merged ranges left after removing the holes."""
    sources = merge(ranges)
    holes = merge(holes)
    result = []
    index = 0
    for start, end in sources:
        while index < len(holes) and holes[index][0] <= end:
            hole_start, hole_end = holes[index]
            if start < hole_start:
                result.append((start, hole_start - 1))
            start = max(start, hole_end + 1)
            if hole_end > end:
                break  # This hole may also cover the next source.
            index += 1
        if start <= end:
            result.append((start, end))
    return result


def count(ranges):
    """Count the distinct integers covered by the ranges."""
    return sum(end - start + 1 for start, end in merge(ranges))
